package com.mo.economy_system.target.forge1201.network;
import com.mojang.logging.LogUtils;import com.mo.economy_system.common.market.*;import com.mo.economy_system.common.network.PurchaseSalesOrderMessage;import com.mo.economy_system.core.economy_system.*;import com.mo.economy_system.core.economy_system.market.MarketSavedData;import com.mo.economy_system.platform.EconomyServices;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraftforge.network.NetworkEvent;import org.slf4j.Logger;import java.util.*;import java.util.function.Supplier;
final class Forge1201PurchaseSalesOrderHandler{private static final Logger LOGGER=LogUtils.getLogger();static void handle(PurchaseSalesOrderMessage m,Supplier<NetworkEvent.Context>s){NetworkEvent.Context n=s.get();ServerPlayer buyer=n.getSender();if(buyer!=null)execute(m,buyer);n.setPacketHandled(true);}private static void execute(PurchaseSalesOrderMessage m,ServerPlayer buyer){PurchaseSalesOrderOutcome o;EconomySavedData accounts;try{accounts=EconomySavedData.getInstance(buyer.serverLevel());MarketSavedData market=MarketSavedData.getInstance(buyer.serverLevel());Forge1201TransactionalInventoryAdapter inventory=new Forge1201TransactionalInventoryAdapter(buyer);o=PurchaseSalesOrderService.execute(m,new PurchaseSalesOrderService.Context(buyer.getUUID(),inventory,inventory,new Accounts(accounts,buyer),new Repository(market),reporter()));}catch(RuntimeException e){LOGGER.error("Sales purchase infrastructure failed buyer={} tradeId={}",buyer.getUUID(),m.tradeId(),e);try{buyer.sendSystemMessage(Component.translatable(PurchaseSalesOrderFeedback.key(PurchaseSalesOrderResult.PAYMENT_FAILED)));}catch(RuntimeException ignored){}return;}if(o.marketChanged())isolate("broadcast",m.tradeId(),()->Forge1201MarketInvalidation.broadcast(buyer));isolate("buyer-feedback",m.tradeId(),()->feedback(buyer,o));if(o.result()==PurchaseSalesOrderResult.SUCCESS)isolate("seller-notice",m.tradeId(),()->notifySeller(buyer,accounts,o.purchasedOrder().orElseThrow()));}private static void feedback(ServerPlayer buyer,PurchaseSalesOrderOutcome o){if(o.result()!=PurchaseSalesOrderResult.SUCCESS){buyer.sendSystemMessage(Component.translatable(PurchaseSalesOrderFeedback.key(o.result())));return;}MarketOrder order=o.purchasedOrder().orElseThrow();buyer.sendSystemMessage(Component.translatable(PurchaseSalesOrderFeedback.key(o.result()),displayName(buyer,order),order.quantity(),order.totalPrice()));}private static Object displayName(ServerPlayer p,MarketOrder o){try{return EconomyServices.platform().itemStacks().restoreSnapshot(o.item(),p.serverLevel().registryAccess()).orElseThrow().getHoverName();}catch(RuntimeException e){LOGGER.error("Purchase display item restore failed tradeId={}",o.tradeId(),e);return o.item().itemId();}}private static void notifySeller(ServerPlayer buyer,EconomySavedData accounts,MarketOrder order){Component notice=Component.translatable("message.market.purchase.seller_notice",displayName(buyer,order),order.quantity(),buyer.getName(),order.totalPrice());ServerPlayer seller=buyer.server.getPlayerList().getPlayer(order.sellerId());if(seller!=null)seller.sendSystemMessage(notice);else accounts.storeOfflineMessage(order.sellerId(),notice.getString());}private static void isolate(String stage,UUID id,Runnable r){try{r.run();}catch(RuntimeException e){LOGGER.error("Sales purchase post-commit failure stage={} tradeId={}",stage,id,e);}}private record Repository(MarketSavedData d)implements PurchaseSalesOrderService.Repository{public MarketOrder find(UUID id){return d.getOrder(id);}public SalesOrderRemovalResult removeSalesTransactional(UUID id){return d.removeSalesTransactional(id);}}private record Accounts(EconomySavedData d,ServerPlayer buyer)implements PurchaseSalesOrderService.Accounts{public BalanceTransferResult preview(UUID seller,int amount){return d.previewTransferExact(buyer.getUUID(),seller,amount);}public BalanceTransferResult transfer(UUID seller,int amount){return d.transferExact(buyer.getUUID(),seller,amount,"市场交易","购买销售订单","销售订单收入");}}private static PurchaseSalesOrderService.FailureReporter reporter(){return(t,b,s,g,r,i,o,e)->LOGGER.error("Sales purchase failure tradeId={} buyer={} seller={} stage={} result={} inventoryRollback={} orderRestore={}",t,b,s,g,r,i,o,e);}}
